private int updateCallGraph(){
  int all_virtual_edges=0, n_obsoleted=0;
  boolean keep_this_edge;
  CgEdge p, q, temp;
  for (int i=1; i < n_func; ++i) {
    p=call_graph[i];
    q=null;
    while (p != null) {
      if (vis_cg[i] == 0) {
        p.is_obsoleted=true;
      }
 else       if (p.base_var != null && (!thread_run_callsites.contains(p.sootEdge.srcStmt()))) {
        keep_this_edge=false;
        ++all_virtual_edges;
        IVarAbstraction pn=consG.get(p.base_var).getRepresentative();
        if (pn != null) {
          SootMethod sm=p.sootEdge.tgt();
          for (          AllocNode an : pn.get_all_points_to_objects()) {
            Type t=an.getType();
            if (t == null)             continue;
 else             if (t instanceof AnySubType)             t=((AnySubType)t).getBase();
 else             if (t instanceof ArrayType)             t=RefType.v("java.lang.Object");
            if (Scene.v().getOrMakeFastHierarchy().resolveConcreteDispatch(((RefType)t).getSootClass(),sm) == sm) {
              keep_this_edge=true;
              break;
            }
          }
          if (keep_this_edge == false) {
            p.is_obsoleted=true;
            ++n_obsoleted;
          }
        }
 else {
          System.err.println();
          throw new RuntimeException("In update_call_graph: oops, what's up?");
        }
      }
      temp=p.next;
      if (p.is_obsoleted == false) {
        p.next=q;
        q=p;
      }
 else {
        obsoletedEdges.add(p);
      }
      p=temp;
    }
    call_graph[i]=q;
  }
  ps.printf("Totally %d virtual edges, we find %d of them are obsoleted.\n",all_virtual_edges,n_obsoleted);
  return n_obsoleted;
}
